+
+        var_dump($tab);
+        echo"<br/>";
+        
+        echo"<br/>";
+        echo"<b>Tablica od początku do końca:</b><br/>";
+        foreach($tab as $v){
+            echo $v . "<br>";
+        };
+
+        echo"<br/>";
+        echo"<b>Tablica od końca do początku:</b><br/>";
+        for($i = count($tab) - 1; $i >= 0; $i--) {
+            echo $tab[$i] . "<br>";
+        }
+
+    }
+    zadanie2();
+
+    function zadanie3() {
+        echo "Największa liczba do wylosowania: " .   . "<br>";
+    }
+    zadanie3();
+
+    function zadanie4() {
+        echo"<br/><br/>";
+        echo"<b>Zadanie 4</b><br/>";
+
+        $min_rand = 100;
+        $max_rand = 999;
+
+        $tab = [];
+        for($i = 0; $i < 10; $i++) {
+            $tab[] = rand($min_rand, $max_rand);
+        }
+
+        var_dump($tab);
+        echo"<br/>";
+
+        foreach($tab as $v) {
+            echo $v . "<br>";
+        }
+
+        echo "<br/>";
+
+        $min = 0;
+        $max = 0;
+
+        $i = 0;
+        $min = $tab[$i];
+        $max = $tab[$i];
+            
+        foreach($tab as $v) {
+            if($v < $min) {
+                $min = $v;
+            }
+            if($v > $max) {
+                $max = $v;
+            }
+        }
+
+        $avg = 0;
+                foreach($tab as $v) {
+            $avg += $v;
+        }
+        $avg = $avg / count($tab);
+        
+        echo "Minimalna wartość: " . $min . "<br>";
+        echo "Maksymalna wartość: " . $max . "<br>";
+        echo "Średnia wartość: " . $avg . "<br>";
+
+        
+
+        return ["max_rand" => $max_rand, "tablica" => $tab, "min" => $min, "max" => $max, "avg" => $avg];
+    }
+    $res = zadanie4();
+
+    function zadanie5($tab) {
+        echo"<br/><br/>";
+        echo"<b>Zadanie 5</b><br/>";
+        
+        echo "<b>Liczby pierwsze:</b><br/>";
+
+        $found = false;
+
+        foreach ($tab as $v) {
+            if (czyPierwsza($v)) {
+                echo $v . "<br>";
+                $found = true;
+            }
+        }
+
+        if (!$found) {
+            echo "Brak liczb pierwszych w tablicy.<br>";
+        }
+    }
+
+    zadanie5($res["tablica"]);
+
+    function zadanie6($data) {
+        echo"<br/><br/>";
+        echo"<b>Zadanie 6</b><br/>";
+
+        $min = $data["min"];
+        $max = $data["max"];
+
+        $wynik = nwd($min, $max);
+
+        echo "Min: $min <br>";
+        echo "Max: $max <br>";
+        echo "NWD(min, max): $wynik <br>";
+    }
+
+    zadanie6($res);
